+        for (size_t j = i; j < end; ++j) {
+            int64_t val = in[j];
+            uint8_t low_byte = val & 255;
+            int sub_idx = j % kSubHistCount;
+            sub_hist[sub_idx][low_byte]++;
+            sum += val;
